from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Wrong number of fields")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    def parse_field(field, min_val, max_val, is_dow=False):
        if not field:
            raise ValueError("Empty field")

        values = set()
        items = field.split(',')

        for item in items:
            if not item:
                raise ValueError("Empty item")

            # Check for step
            step = 1
            if '/' in item:
                parts = item.split('/')
                if len(parts) != 2:
                    raise ValueError("Invalid step format")
                base, step_str = parts
                if not step_str.isdigit():
                    raise ValueError("Non-digit step")
                step = int(step_str)
                if step < 1:
                    raise ValueError("Step must be >= 1")
            else:
                base = item

            # Parse base
            if base == '*':
                start = min_val
                end = max_val
            elif '-' in base:
                parts = base.split('-')
                if len(parts) != 2:
                    raise ValueError("Invalid range format")
                a_str, b_str = parts
                if not a_str.isdigit() or not b_str.isdigit():
                    raise ValueError("Non-digit in range")
                a = int(a_str)
                b = int(b_str)
                if a > b:
                    raise ValueError("A > B in range")
                if a < min_val or a > max_val:
                    raise ValueError("Out of range in range")
                if b < min_val or b > max_val:
                    raise ValueError("Out of range in range")
                start = a
                end = b
            else:
                if not base.isdigit():
                    raise ValueError("Non-digit in value")
                val = int(base)
                if val < min_val or val > max_val:
                    raise ValueError("Out of range value")
                if '/' in item:
                    start = val
                    end = max_val
                else:
                    start = val
                    end = val

            for v in range(start, end + 1, step):
                if is_dow:
                    if v == 7:
                        v = 0
                values.add(v)

        return values

    minutes = parse_field(minute_field, 0, 59)
    hours = parse_field(hour_field, 0, 23)
    doms = parse_field(dom_field, 1, 31)
    months = parse_field(month_field, 1, 12)
    dows = parse_field(dow_field, 0, 7, is_dow=True)

    # Normalize dows: 7 -> 0
    if 7 in dows:
        dows.add(0)
        dows.discard(7)

    dom_restricted = dom_field != "*"
    dow_restricted = dow_field != "*"

    # Start from the next minute strictly after `after`
    # Truncate seconds and microseconds, then add 1 minute
    current = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    # Search up to 3000 days
    limit = after + timedelta(days=3000)

    while current <= limit:
        if current.month not in months:
            # Jump to the first day of the next month
            if current.month == 12:
                current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
            continue

        # Check day of month and day of week
        # Python's weekday(): Monday=0, Sunday=6
        # Cron's day of week: Sunday=0, Monday=1, ..., Saturday=6
        py_weekday = current.weekday()
        cron_weekday = (py_weekday + 1) % 7

        dom_match = current.day in doms
        dow_match = cron_weekday in dows

        if dom_restricted and dow_restricted:
            day_match = dom_match or dow_match
        else:
            day_match = dom_match and dow_match

        if not day_match:
            current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        if current.hour not in hours:
            # Jump to next hour
            if current.hour == 23:
                current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            else:
                current = current.replace(hour=current.hour + 1, minute=0)
            continue

        if current.minute not in minutes:
            # Jump to next minute
            if current.minute == 59:
                if current.hour == 23:
                    current = (current + timedelta(days=1)).replace(hour=0, minute=0)
                else:
                    current = current.replace(hour=current.hour + 1, minute=0)
            else:
                current = current.replace(minute=current.minute + 1)
            continue

        return current

    raise ValueError("No match within 3000 days")
