        if t not in deps:
            in_degree[t] = 0

    heap = [t for t in all_targets if in_degree[t] == 0]
    heapq.heapify(heap)
    order = []

    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for dependent in dependents[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(order) == len(all_targets):
        return order

    remaining = set(all_targets) - set(order)

    adj = {}
    for t in remaining:
        deps_list = deps.get(t, [])
        adj[t] = [d for d in deps_list if d in remaining]

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {t: WHITE for t in remaining}
    cycle = None

    def dfs(node, stack):
        nonlocal cycle
        color[node] = GRAY
        stack.append(node)
        for neighbor in adj[node]:
            if color[neighbor] == GRAY:
                idx = stack.index(neighbor)
                cycle = stack[idx:]
                return True
            elif color[neighbor] == WHITE:
