import heapq


class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = cycle


def build_order(deps):
    """`deps` maps each target (str) to an iterable of targets it depends on (duplicates allowed). Targets that only
    appear as dependencies are leaves. Return a list of ALL targets in which every target comes after all of its
    dependencies. Whenever several targets are ready, the lexicographically smallest is placed first, so the
    order is unique.

    If the graph has a cycle (including a target depending on itself), raise CycleError(cycle) where `cycle`
    lists the targets on the cycle: it starts with the lexicographically smallest target ON the cycle, each element
    depends on the next one, and it ends by repeating the first element (e.g. ["a", "b", "a"], or ["x", "x"]).
    Targets that merely lead into a cycle are not part of it. Inputs with cycles contain exactly one cycle.
    `deps` must not be modified.
    """
    all_targets = set(deps.keys())
    for target, dep_list in deps.items():
        for d in dep_list:
            all_targets.add(d)

    dependents = {t: [] for t in all_targets}
    in_degree = {t: 0 for t in all_targets}

    for target, dep_list in deps.items():
        seen = set()
        for d in dep_list:
            if d not in seen:
                seen.add(d)
                dependents[d].append(target)
                in_degree[target] += 1

    for t in all_targets:
        if t not in deps:
            in_degree[t] = 0

    heap = [t for t in all_targets if in_degree[t] == 0]
    heapq.heapify(heap)
    order = []

    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for dependent in dependents[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(order) == len(all_targets):
        return order

    remaining = set(all_targets) - set(order)

    adj = {}
    for t in remaining:
        deps_list = deps.get(t, [])
        adj[t] = [d for d in deps_list if d in remaining]

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {t: WHITE for t in remaining}
    cycle = None

    def dfs(node, stack):
        nonlocal cycle
        color[node] = GRAY
        stack.append(node)
        for neighbor in adj[node]:
            if color[neighbor] == GRAY:
                idx = stack.index(neighbor)
                cycle = stack[idx:]
                return True
            elif color[neighbor] == WHITE:
                if dfs(neighbor, stack):
                    return True
        stack.pop()
        color[node] = BLACK
        return False

    for t in sorted(remaining):
        if color[t] == WHITE:
            if dfs(t, []):
                break

    if cycle is None:
        raise CycleError(list(remaining))

    min_idx = 0
    for i in range(len(cycle)):
        if cycle[i] < cycle[min_idx]:
            min_idx = i

    rotated = cycle[min_idx:] + cycle[:min_idx]
    rotated.append(rotated[0])

    raise CycleError(rotated)
